{
  "search_strategies": [
    {
      "name": "eip7702_authorization",
      "keywords": ["authorization", "nonce", "7702", "delegate", "designat"],
      "file_patterns": ["**/core/types/*.go", "**/core/state_transition*.go"],
      "search_patterns": ["func.*[Aa]uthor", "type.*[Aa]uthor", "nonce"]
    },
    {
      "name": "encode_account",
      "keywords": ["encode_account", "storage_root", "merkle"],
      "file_patterns": ["**/core/types/*.go", "**/trie/*.go"],
      "search_patterns": ["func.*[Ee]ncode", "storage.*[Rr]oot"]
    },
    {
      "name": "type_aliases",
      "keywords": ["Address", "Root", "VersionedHash", "Bloom", "Hash32", "Bytes20"],
      "file_patterns": ["**/core/types/*.go", "**/common/*.go"],
      "search_patterns": ["type.*(Address|Root|Hash|Bloom)"]
    },
    {
      "name": "deposit_requests",
      "keywords": ["deposit_requests", "parse_deposit", "requests_hash"],
      "file_patterns": ["**/core/types/*.go", "**/beacon-chain/**/*.go"],
      "search_patterns": ["func.*[Dd]eposit", "func.*[Rr]equest"]
    },
    {
      "name": "withdrawals",
      "keywords": ["withdrawal", "execute_withdrawal", "apply_withdrawal"],
      "file_patterns": ["**/core/*.go", "**/consensus/*.go"],
      "search_patterns": ["func.*[Ww]ithdraw"]
    }
  ]
}
